#!/usr/bin/env python3
from pathlib import Path
import json,shutil,re
from xml.etree import ElementTree as ET

ROOT=Path(__file__).resolve().parent;OLD=ROOT.parent/'2026-10-homepad-v2/03-dwell'
(ROOT/'source').mkdir(exist_ok=True)
(ROOT/'concepts').mkdir(exist_ok=True)
shutil.copyfile(OLD/'icon.svg',ROOT/'source/original-dwell.svg')
shutil.copyfile(OLD/'icon-1024.png',ROOT/'source/original-dwell-1024.png')
HOUSE='M256 488 C256 466 268 446 288 430 L480 286 Q512 260 544 286 L736 430 C756 446 768 466 768 488 V700 Q768 752 716 752 H308 Q256 752 256 700 Z'
DEFS=f'''<linearGradient id="canvas" x1=".1" y1="0" x2=".8" y2="1"><stop stop-color="#FFFFFF"/><stop offset=".65" stop-color="#FAFBFA"/><stop offset="1" stop-color="#EFF2F1"/></linearGradient><linearGradient id="body" x1="0" y1="0" x2=".7" y2="1"><stop stop-color="#7BD7BB"/><stop offset=".55" stop-color="#48BEA6"/><stop offset="1" stop-color="#2AA68F"/></linearGradient><linearGradient id="mint" x1="0" y1="0" x2=".8" y2="1"><stop stop-color="#A5E5C4"/><stop offset="1" stop-color="#67CFA8"/></linearGradient><linearGradient id="warm" x1="0" y1="0" x2=".7" y2="1"><stop stop-color="#F7D79A"/><stop offset="1" stop-color="#ECC17A"/></linearGradient><filter id="settle" x="-20%" y="-20%" width="140%" height="145%" color-interpolation-filters="sRGB"><feDropShadow dx="0" dy="7" stdDeviation="9" flood-color="#32AA94" flood-opacity=".09"/></filter><clipPath id="house-clip"><path d="{HOUSE}"/></clipPath>'''
IDEAS=[
 dict(id='01-warm-window',number='01',name='暖窗',concept='把亮起的窗，收进一个完整的家。',structure='连续屋形＋内凹窗洞',defs='''<mask id="window-hole"><rect width="1024" height="1024" fill="white"/><rect x="428" y="478" width="244" height="218" rx="54" fill="black"/></mask>''',art=f'''<path d="{HOUSE}" fill="url(#body)" mask="url(#window-hole)"/><rect x="464" y="514" width="172" height="146" rx="34" fill="url(#warm)"/>'''),
 dict(id='02-light-corner',number='02',name='光隅',concept='两片饱满的面，把一角暖光留给家。',structure='斜向双块面＋圆润收口',defs='',art='''<path d="M256 488 C256 466 268 446 288 430 L480 286 Q512 260 544 286 L718 418 C738 434 750 450 750 472 Q750 482 742 492 L522 728 Q500 752 480 752 H308 Q256 752 256 700 Z" fill="url(#body)"/><path d="M748 548 Q768 526 768 556 V700 Q768 752 716 752 H548 Q526 752 544 732 Z" fill="url(#warm)"/>'''),
 dict(id='03-one-roof',number='03',name='同檐',concept='两侧的空间，围出一扇亮着的窗。',structure='双块面围合＋中央暖窗',defs='',art='''<path d="M256 488 C256 466 268 446 288 430 L456 286 Q480 267 480 298 V414 Q480 450 444 450 H440 Q400 450 400 490 V708 Q400 752 356 752 H308 Q256 752 256 700 Z" fill="url(#body)"/><path d="M256 488 C256 466 268 446 288 430 L456 286 Q480 267 480 298 V414 Q480 450 444 450 H440 Q400 450 400 490 V708 Q400 752 356 752 H308 Q256 752 256 700 Z" transform="translate(1024 0) scale(-1 1)" fill="url(#mint)"/><rect x="432" y="546" width="160" height="206" rx="44" fill="url(#warm)"/>'''),
 dict(id='04-layered-home',number='04',name='叠居',concept='让一侧稍稍转出来，家形仍然完整。',structure='正面与侧面组成一个家',defs='',art='''<path d="M656 492 L768 436 V650 Q768 686 736 704 L604 752 Q656 752 656 700 Z" fill="url(#body)"/><path d="M256 492 C256 468 268 450 286 434 L428 302 Q456 278 484 302 L626 434 C646 450 656 468 656 492 V700 Q656 752 604 752 H308 Q256 752 256 700 Z" fill="url(#body)"/><path d="M456 290 L544 246 Q568 232 592 254 L748 410 Q768 426 768 436 L656 492 Q656 468 626 434 L484 302 Q470 290 456 290 Z" fill="url(#mint)"/><rect x="376" y="526" width="144" height="148" rx="36" fill="url(#warm)"/>'''),
]

for idea in IDEAS:
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="1024" viewBox="0 0 1024 1024" role="img" aria-labelledby="title desc"><title id="title">HomePad Dwell exploration · {idea['name']}</title><desc id="desc">{idea['structure']}. Original HomePad concept, compared to the original Dwell. Design exploration only.</desc><defs>{DEFS}{idea['defs']}</defs><rect width="1024" height="1024" fill="url(#canvas)"/><g id="homepad-symbol" filter="url(#settle)">{idea['art']}</g></svg>'''
 (ROOT/'concepts'/f'{idea["id"]}.svg').write_text(svg)

all_items=[dict(id='original',number='原版',name='家窗',concept='柔和、饱满的三块面，作为这次的基准。',structure='第二轮原始 Dwell',original=True)]+IDEAS
def source(idea):return 'source/original-dwell.svg' if idea.get('original') else f'concepts/{idea["id"]}.svg'
def icon(idea,size):return f'<div class="app-icon" style="width:{size}px;height:{size}px"><img class="masked" src="{source(idea)}" alt="{idea["name"]}"></div>'
cards=''.join(f'''<article class="card {'reference' if v.get('original') else ''}"><div class="tag"><span>{v['number']}</span><b>{'审美基准' if v.get('original') else '构形探索'}</b></div><div class="large">{icon(v,276)}</div><h2>{v['name']}</h2><p>{v['concept']}</p><small>{v['structure']}</small><div class="at60"><span>60 px 实际大小</span>{icon(v,60)}</div></article>''' for v in all_items)
html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HomePad · 回到家窗</title><style>
*{{box-sizing:border-box}}:root{{color-scheme:light}}body{{margin:0;background:#f1f3ee;color:#2f4036;font:16px/1.5 -apple-system,BlinkMacSystemFont,"Helvetica Neue","PingFang SC",sans-serif;-webkit-font-smoothing:antialiased}}.board{{width:1800px;max-width:100%;margin:0 auto;padding:49px 64px 38px;background:#f4f6f1}}.eyebrow{{display:flex;justify-content:space-between;color:#91a18a;font-size:11px;letter-spacing:2px;font-weight:550}}h1{{font-size:54px;font-weight:550;line-height:1.2;letter-spacing:-1.7px;margin:24px 0 14px}}.intro{{font-size:18px;color:#8c9e82;margin:0}}.cards{{display:grid;grid-template-columns:repeat(5,1fr);gap:18px;margin:37px 0 28px}}.card{{background:#fff;border:1px solid #e0e7d9;border-radius:25px;padding:22px 21px 22px;overflow:hidden}}.reference{{background:#fafcf7;border-style:dashed}}.tag{{display:flex;justify-content:space-between;align-items:center;font-size:13px;letter-spacing:1px;color:#7b9670;min-height:25px}}.tag b{{font-size:10px;color:#a4b499;font-weight:400;letter-spacing:1px}}.large{{height:316px;display:flex;align-items:center;justify-content:center}}.app-icon{{display:inline-block;flex-shrink:0;filter:drop-shadow(0 7px 13px #32492c0e)}}.app-icon img{{display:block;width:100%;height:100%}}.masked{{clip-path:url(#mask)}}h2{{font-size:27px;letter-spacing:.6px;font-weight:550;margin:0 0 9px}}.card p{{font-size:13px;line-height:1.9;min-height:52px;color:#819574;margin:0 0 14px}}.card>small{{display:block;font-size:10px;color:#acbba1;letter-spacing:.5px;min-height:20px}}.at60{{display:flex;align-items:center;justify-content:space-between;gap:20px;border-top:1px solid #eaf0e4;padding-top:18px;margin-top:22px}}.at60>span{{font-size:10px;color:#9eaf92;letter-spacing:.6px}}.footer{{display:flex;justify-content:space-between;gap:25px;border-top:1px solid #dce5d3;padding-top:24px;color:#98aa8c;font-size:12px;line-height:1.9}}@media(max-width:1200px){{.board{{padding:30px 22px}}h1{{font-size:40px}}.cards{{grid-template-columns:repeat(2,1fr)}}.footer{{flex-direction:column}}}}@media(max-width:650px){{.cards{{grid-template-columns:1fr}}}}
</style><svg width="0" height="0" style="position:absolute"><defs><clipPath id="mask" clipPathUnits="objectBoundingBox"><path d="M.22 0H.78C.95 0 1 .05 1 .22V.78C1 .95 .95 1 .78 1H.22C.05 1 0 .95 0 .78V.22C0 .05 .05 0 .22 0Z"/></clipPath></defs></svg><main class="board"><div class="eyebrow"><span>HOMEPAD / BACK TO DWELL</span><span>05 · FORM EXPLORATIONS</span></div><h1>还是那个柔软的家，换四种构形。</h1><p class="intro">以原始「家窗」为基准，保留完整轮廓、饱满块面和一处暖光。</p><div class="cards">{cards}</div><div class="footer"><span>原版保留并列；新方案改变内部空间关系，不以换色代替构形。</span><span>各方案同等画布、相近占比，附实际 60 px 对比。</span><span>创意探索，未作最终选择 · AppIcon 保持原样</span></div></main></html>'''
(ROOT/'index.html').write_text(html)
(ROOT/'concepts.json').write_text(json.dumps([{k:v[k] for k in ['id','number','name','concept','structure']} for v in IDEAS],ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'output':str(ROOT),'new_forms':4,'reference':'Original round-2 Dwell'},ensure_ascii=False))
